\")</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; For i = LBound(allowedArray) To UBound(allowedArray)</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; allowedList(Trim(LCase(allowedArray(i)))) = True</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Next i</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Set ws = ActiveSheet</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; Const colS As Long = 19 \' Kolom S</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; lastRow = ws.Cells(ws.Rows.Count, colS).End(xlUp).Row</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; \' Loop dari bawah agar aman saat menghapus baris</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; For i = lastRow To 2 Step -1</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; nama = Trim(LCase(ws.Cells(i, colS).Value))</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; \' Jika nama tidak ada di daftar ? hapus baris</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; If Not allowedList.exists(nama) Then</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ws.Rows(i).Delete</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp; End If</span></div><div><span style=\"font-size: 15.2px;\">&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span></div><div><span style=\"font-size: 1