si /. Jika Use% tinggi, lanjut ke langkah berikutnya.</p></li><li><p data-path-to-node=\"7,1,0\"><b data-path-to-node=\"7,1,0\" data-index-in-node=\"0\">Lacak Folder Terbesar di /var</b></p><response-element class=\"\" ng-version=\"0.0.0-PLACEHOLDER\"><!----><!----><!----><!----><!----><!----><code-block _nghost-ng-c3678280791=\"\" class=\"ng-tns-c3678280791-679 ng-star-inserted\"><!----><!----><div _ngcontent-ng-c3678280791=\"\" class=\"code-block ng-tns-c3678280791-679 ng-animate-disabled ng-trigger ng-trigger-codeBlockRevealAnimation\" jslog=\"223238;track:impression,attention;BardVeMetadataKey:[[&quot;r_1e6aaee7f05c90c2&quot;,&quot;c_5565fea761e1b769&quot;,null,&quot;rc_aa9212d69f708301&quot;,null,null,&quot;id&quot;,null,1,null,null,1,0]]\" data-hveid=\"0\" decode-data-ved=\"1\" data-ved=\"0CAAQhtANahgKEwje19Pct4WVAxUAAAAAHQAAAAAQqQk\"><div _ngcontent-ng-c3678280791=\"\" class=\"code-block-decoration header-formatted gds-title-s ng-tns-c3678280791-679 ng-star-inserted\"><span _ngcontent-ng-c3678280791=\"\" class=\"ng-tns-c3678280791-679\">Bash</span><div _ngcontent-ng-c3678280791=\"\" class=\"buttons ng-tns-c3678280791-679 ng-star-inserted\"><!----><button _ngcontent-ng-c3678280791=\"\" aria-label=\"Download code\" mat-icon-button=\"\" gemtooltip=\"Download code\" class=\"mdc-icon-button mat-mdc-icon-button mat-mdc-button-base mat-mdc-tooltip-trigger download-button ng-tns-c3678280791-679 mat-unthemed ng-star-inserted\" mat-ripple-loader-uninitialized=\"\" mat-ripple-loader-class-name=\"mat-mdc-button-ripple\" mat-ripple-loader-centered=\"\"><span class=\"mat-mdc-button-persistent-ripple mdc-icon-button__ripple\"></span><mat-icon _ngcontent-ng-c3678280791=\"\" role=\"img\" fonticon=\"download\" class=\"mat-icon notranslate gds-icon-s google-symbols mat-ligature-font mat-icon-no-color\" aria-hidden=\"true\" data-mat-icon-type=\"font\" data-mat-icon-name=\"download\"></mat-icon><!----><span class=\"mat-focus-indicator\"></span><span class=\"mat-mdc-button-touch-target\"></span></button><!----><!----><!----><!----><!----><button _ngcontent-ng-c3678280791=\"\" aria-label=\"Copy code\" mat-icon-button=\"\" gemtooltip=\"Copy code\" class=\"mdc-icon-button mat-mdc-icon-button mat-mdc-button-base mat-mdc-tooltip-trigger copy-button ng-tns-c3678280791-679 mat-unthemed ng-star-inserted\" mat-ripple-loader-uninitialized=\"\" mat-ripple-loader-class-name=\"mat-mdc-button-ripple\" mat-ripple-loader-centered=\"\" jslog=\"179062;track:generic_click,impression;BardVeMetadataKey:[[&quot;r_1e6aaee7f05c90c2&quot;,&quot;c_5565fea761e1b769&quot;,null,&quot;rc_aa9212d69f708301&quot;,null,null,&quot;id&quot;,null,1,null,null,1,0]];mutable:true\"><span class=\"mat-mdc-button-persistent-ripple mdc-icon-button__ripple\"></span><mat-icon _ngcontent-ng-c3678280791=\"\" role=\"img\" fonticon=\"content_copy\" class=\"mat-icon notranslate gds-icon-s google-symbols mat-ligature-font mat-icon-no-color\" aria-hidden=\"true\" data-mat-icon-type=\"font\" data-mat-icon-name=\"content_copy\"></mat-icon><!----><span class=\"mat-focus-indicator\"></span><span class=\"mat-mdc-button-touch-target\"></span></button><!----><!----><!----></div><!----><!----></div><!----><div _ngcontent-ng-c3678280791=\"\" class=\"formatted-code-block-internal-container ng-tns-c3678280791-679\"><div _ngcontent-ng-c3678280791=\"\" class=\"animated-opacity ng-tns-c3678280791-679\"><!----><pre _ngcontent-ng-c3678280791=\"\" class=\"ng-tns-c3678280791-679\"><code _ngcontent-ng-c3678280791=\"\" role=\"text\" data-test-id=\"code-content\" class=\"code-container formatted ng-tns-c3678280791-679\">du -h --max-depth=1 /var/ 2&gt;/dev/null | sort -rh | head -n 5\r\n</code></pre><!----></div></div></div><!----><!----><!----></code-block><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!----><!-