br>\'427002020325\',<br>\'427000645024\',<br>\'250001335325\',<br>\'250000101526\',<br>\'437000030825\',<br>\'280000861125\',<br>\'261000133925\',<br>\'422000090226\',<br>\'422901603425\',<br>\'248001708524\',<br>\'244900072126\',<br>\'418903496226\',<br>\'254000659425\',<br>\'437000110725\',<br>\'240000536824\',<br>\'248000094026\',<br>\'254000759025\',<br>\'254000975424\',<br>\'303901901425\',<br>\'418002026325\',<br>\'240000134925\',<br>\'278900049126\',<br>\'254000470126\',<br>\'427900139426\',<br>\'244900264125\',<br>\'237001429323\',<br>\'321003695825\',<br>\'402000947623\',<br>\'402900256626\',<br>\'507000080126\',<br>\'248000447926\',<br>\'275002027024\',<br>\'275000372026\',<br>\'426900837524\',<br>\'426900837724\',<br>\'426000353624\',<br>\'426900519424\',<br>\'280000665625\',<br>\'426000243224\',<br>\'418900245725\',<br>\'421900335626\',<br>\'240900109426\',<br>\'321004503526\',<br>\'437000075025\'<br>)<br><br><br><br>4. Pastikan jgn slah hapus,yang kontrak meta failed yg gak dihapus<br><br>5. kirim sms seperti bisa yg sering dijalanin sms project pag<br><br>6. generate result sampe INSERT result<br>&nbsp; &nbsp;http://172.16.30.33:3108/c_ws_sms<br>&nbsp;&nbsp;<br>7. generate result&nbsp; wa project ke stg_coll_result_sms<br>&nbsp; &nbsp;http://172.16.30.33:3108/c_ws_whatsapp<br><br>INSERT INTO db_sim.STG_COLLECTION_RESULT_SMS_TASK (<br>&nbsp; stg_no_lkp_sms,<br>&nbsp; stg_seqno,<br>&nbsp; contract_no,<br>&nbsp; flag,<br>&nbsp; result,<br>&nbsp; created_timestamp<br>)<br>SELECT<br>&nbsp; a.stg_no_lkp_sms,<br>&nbsp; a.stg_seqno,<br>&nbsp; a.CONTRACT_NO,<br>&nbsp; \'N\',<br>&nbsp; c.result,<br>&nbsp; NOW()<br>FROM&nbsp;<br>&nbsp; STG_COLLECTION_SMS_TASK a<br>JOIN<br>&nbsp; STG_COLLECTION_RESULT_SMS_TASK_april_2026 c<br>ON&nbsp;<br>&nbsp; &nbsp;a.contract_no = c.contract_no<br>AND&nbsp;<br>&nbsp; &nbsp;c.created_timestamp BETWEEN \'2026-09-01 00:00:00\' AND \'2026-09-01 23:59:59\'<br>AND&nbsp;<br>&nbsp; &nbsp;a.contract_no NOT IN (SELECT CONTRACT_NO FROM STG_COLLECTION_RESULT_SMS_TASK)&nbsp; &nbsp;<br><br>8.&nbsp; pastikan jumlah DATA sesuai dengan final SMS project<br>poin 8 done<br><br>pakai QUERY ini broo<br><br>/*`db_sms_smartcoll`*/<br>SELECT TIME(`created_timestamp`),COUNT(*) \'jumlah\'<br>FROM `sms_result`<br>GROUP BY TIME(`created_timestamp`)WITH ROLLUP ;<br><br>9.&nbsp; Kirm sms project lewat ssh ke stagging FIF&nbsp; 🚀🚀🚀🚀🚀</p>','uploads/meta failed.txt',2),(83,'2026-09-24 07:48:30','Database','KIRIM MTF AFTER MTF KRANGGAN DAN SEMARANG LC','pengiriman data MTF KRANGGAN dan SEMARANG LC dan MTF KRANGGAN sudah generate VA','<p>lakukan ini sblm kirim data ke mtf<br>untuk melakukan klik button ini di BE MTF REG link http://172.16.30.25:500/c_wa_blast..<br>untuk kirim result wa blast ke STG MTF, setelah TL melakukan klik Generate Data dan dilakukan sebelum kirim ke CORE MTF&nbsp; ya<br><br>Generate Va MTF sukses<br><br>pengiriman MTF after LC<br><br>PENGIRIMAN DC AUTODIAL KE STG MTF<br>19:00 Pengiriman Result DC AUTODIAL ke STG MTF<br>LINK: http://147.139.202.192:5000/c_send_result_to_stg<br>Pengiriman Result DC C2C ke STG MTF<br>LINK : http://147.139.202.192:1400/c_send_result_to_stg<br><br>PENGIRIMAN DC C2C KE STG MTF<br>19:00 Pengiriman Result DC C2C KRANGGAN ke STG MTF<br>LINK: http://172.16.30.25:500/ws/scheduler/getdataresultforstaging<br>19:15 Pengiriman Result DC C2C SEMARANG ke STG MTF<br>LINK: http://172.16.30.25:700/ws/scheduler/getdataresultforstaging<br><br>PENGIRIMAN OVRS KE STG MTF<br>19:30 Pengiriman Result OVRS NONDC / PROJECT ke STG MTF<br>LINK: http://149.129.194.239:1206/ws/scheduler/getdataresultforstaging<br>19:45 Pengiriman Result OVRS KRANGGAN ke STG MTF<br>LINK: http://147.139.174.90:1206/ws/scheduler/getdataresultforstaging<br>20:00 Pengiriman Result OVRS SEMARANG ke STG MTF<br>LINK: http://149.129.195.57:1206/ws/scheduler/getdataresultforstaging<br><br>PENGIRIMAN SMS MTF KE STG MTF<br>20:15 Pengiriman Result SMS ke STG MTF<br>LINK: http://172.16.30.25:100/ws/scheduler/getdataresultforstaging<br><br>PENGIRIMAN STG MTF KE CORE MTF<br>20:30 Pengiriman Result STG MTF ke Core MTF (Client)<br>LINK: http://172.16.30.25:500/ws/scheduler/sendAPIResult</p>','uploads/MTF KIRIM DATA.txt',2),(86,'2026-09-27 08:14:22','Database','alur baru kalau fif libur (pagi hari)','alur ubah data menjadi non dc setiap tanggal libur nasional atau fif tidak call','<p>Alur&nbsp; Baru jika FIF agent gak ngecall (baik itu tgl merah atau minggu)<br><br>1. jalankan sync di backend menu upload File pilih upload NCL dan Upload NCL number&nbsp;<br>2. pastikan jumlah yg masuk RTN sesuai dengan notif buttonya&nbsp;<br><br>&nbsp; &nbsp; &nbsp; &nbsp; /...cara ngechek syn ncl terbentuk/<br>SELECT DATE(createdTimeStamp),COUNT(*) \'jumlah\'<br>FROM tblViaNcl_sync<br>GROUP BY DATE(createdTimeStamp) WITH ROLLUP&nbsp;<br><br><br>/..........RTN/<br>SELECT stg_lkp_comments,COUNT(*) \'juamlah\'<br>FROM STG_COLLECTION_RESULT<br>WHERE stg_created_time_stamp = CURDATE()<br>AND stg_param = \'RTN\'<br>GROUP BY stg_lkp_comments WITH ROLLUP ;<br><br>3. jalankan Query Insert to NONDC terbaru<br>4. pastikan data RTN tidak ada yang masuk ke nondc nondc<br>/.....jika hasilnya kosong berarti aman/<br>SELECT prod_5.tblCollectionTaskNonDC.contractNo<br>FROM prod_5.tblCollectionTaskNonDC<br>WHERE prod_5.tblCollectionTaskNonDC.contractNo IN(SELECT db_sim.STG_COLLECTION_RESULT.b2b_contract_no FROM db_sim.STG_COLLECTION_RESULT)<br><br>5. chek apakah dimenu filter sesuai apa masih selisih..<br>klau sesuai berarti aman..</p>','uploads/Alur Baru jika FIF gak ngecall.pdf',2),(87,'2026-09-27 08:15:27','Database','query ubah non dc terbaru','Query ubah data menjadi Non Dc terbaru bila tanggal merah libur nasional atau fif tidak call','<p>INSERT IGNORE INTO prod_5.tblCollectionTaskNonDC (<br>noLkp ,<br>  seqN ,<br>  fieldPeople,<br>  tanggalLkd,<br>  team,<br>  noKontrak,<br>  applId,<br>  alamatTagih,<br>  namaCustomer,<br>  telp1,<br>  telp2,<br>  telp3,<br>  emergencyFixedPhone,<br>  emergencyMobilePhone,<br>  aw,<br>  ak,<br>  top,<br>  tglAwal,<br>  tglAkhir,<br>  outStdPkk,<br>  overdue,<br>  angsuran,<br>  objCode,<br>  coyId,<br>  dTetap,<br>  dBerjalan,<br>  bTagih,<br>  ambc,<br>  bnMenurun,<br>  tTnggkn,<br>  objType,<br>  boPol,<br>  engineNo,<br>  frameNo,<br>  pbAwal,<br>  delqReason,<br>  remClass,<br>  pDkh,<br>  objectCodeDescription,<br>  warna,<br>  contractNo,<br>  instNo ,<br>  instAmtPaid,<br>  penaltyAmtPaid,<br>  collFeePaid,<br>  paidDate,<br>  dueDate,<br>  ovdDays,<br>  companyId,<br>  TYPE,<br>  createdDate,<br>  kodeCabang,<br>  uniqueId ,<br>  dateStamp,<br>  TIMESTAMP,<br>   customerNo,<br>  tanggalLahir,<br>  agama,<br>  jenisKelamin,<br>  cycleAwal,<br>  bayarVia,<br>  dedicatedOverdue,<br>  valuable_cust<br>  )<br>SELECT<br>stg_no_lkp,<br>  stg_seqn ,<br>  stg_field_people,<br>  stg_tanggal_lkd ,<br>  stg_team ,<br>  stg_no_kontrak,<br>  stg_appl_id ,<br>  stg_alamat_tagih ,<br>  stg_nama_customer ,<br>  stg_telp1 ,<br>  stg_telp2 ,<br>  stg_telp3 ,<br>  stg_emergency_fixed_phone,<br>  stg_emergency_mobile_phone ,<br>  stg_aw ,<br>  stg_ak ,<br>  stg_top ,<br>  stg_tgl_awal,<br>  stg_tgl_akhir,<br>  stg_outstd_pkk,<br>  stg_overdue ,<br>  stg_angsuran,<br>  stg_obj_code,<br>  stg_coy_id,<br>  stg_d_tetap,<br>  stg_d_brjln,<br>  stg_b_tagih,<br>  stg_ambc ,<br>  stg_bn_menurun,<br>  stg_t_tnggkn ,<br>  stg_obj_type ,<br>  stg_bo_pol ,<br>  stg_engine_no,<br>  stg_frame_no ,<br>  stg_p_b_awal ,<br>  stg_delq_reason,<br>  stg_rem_class,<br>  stg_p_dkh,<br>  stg_object_code_description,<br>  stg_warna,<br>  stg_contract_no,<br>  stg_inst_no,<br>  stg_inst_amt_paid,<br>  stg_penalty_amt_paid,<br>  stg_coll_fee_paid,<br>  stg_paid_date,<br>  stg_due_date,<br>  stg_ovd_days,<br>  stg_company_id,<br>  stg_type,<br>  stg_created_date,<br>  stg_kode_cabang_fif,<br>  CONCAT(stg_no_lkp,stg_seqn),<br>  CURDATE(),<br>  CURTIME(),<br>  stg_customer_no,<br>  stg_tanggal_lahir,<br>  stg_agama,<br>  stg_jenis_kelamin,<br>  stg_cycle_awal,<br>  stg_bayar_via,<br>  0,<br>  stg_flag_valuable_cust<br>FROM db_sim.STG_COLLECTION_TASK USE INDEX (PRIMARY)<br>WHERE <br>db_sim.STG_COLLECTION_TASK.stg_no_kontrak NOT IN(SELECT db_sim.STG_COLLECTION_RESULT.b2b_contract_no FROM db_sim.STG_COLLECTION_RESULT)<br>AND stg_created_date = CURDATE()</p>',NULL,2),(88,'2026-09-27 08:16:39','Database','report sore bila fif libur','report sore bila fif libur tanggal merah atau fif tidak call','<p>=====&nbsp;<br>#KR5&nbsp;<br>=====&nbsp;<br>sms sukses terkirim ke operator&nbsp;<br>+ DC&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; : 0<br>+ nonDC&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;: 47.377<br>+ sms agent&nbsp; &nbsp; &nbsp; &nbsp;: 0&nbsp;<br>+ sms project&nbsp; &nbsp;:&nbsp; 2.117<br>+ sms manual&nbsp; &nbsp; : 0<br><br>#Parameter result<br><br>stg_param jumlah<br><br>MSG-E:&nbsp; &nbsp;4.985<br>MSG-I:&nbsp; &nbsp; &nbsp; 50<br>MSG-S:&nbsp; 42.269<br>MSG-U:&nbsp; &nbsp; &nbsp; 73<br><br><br>total jumlah 47.377<br><br>============&nbsp;<br>#SYNC_NONDC&nbsp;<br>============&nbsp;<br>syncron DATA nondc sukses&nbsp;<br>dan terkirim ke FIF (47.377)<br>&nbsp;<br>================&nbsp;<br>#SYNC_SMS_SMART&nbsp;<br>=================&nbsp;<br>^syncron DATA sms smart sukses dan terkirim ke FIF&nbsp;<br>^ jumlah SMS_TASK = jumlah SMS_RESULT (2.117)&nbsp;<br>&nbsp;<br>===============&nbsp;<br>#REPORT_DATA&nbsp;<br>===============&nbsp;<br>DATA tanggal 26-07-2026&nbsp;<br>sukses terkirim ke staging FIF<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br>- DATA duplikat kontrak tidak ada&nbsp;<br>- NonDC&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;= 47.377<br>- Blank phone&nbsp; &nbsp;=&nbsp; &nbsp; &nbsp; 0<br>- RTN&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;=&nbsp; &nbsp; &nbsp; 0<br>% Total result&nbsp; = 47.377</p>','uploads/report minggu sore dc libur.txt',2),(89,'2026-09-27 08:33:24','Database','alur kirim data sore bila FIF tidak call atau libur nasional','alur kirim data sore bila FIF tidak call atau libur nasional','<p>1. cek wa official <a href=\"http://149.129.232.223:6500/auth/login\" target=\"_blank\">http://149.129.232.223:6500/auth/login</a><br>pastikan data tidak ada yang nyangkut dan sudah 0 untuk prosesnya lalu jalankan query ambil data failednya</p><p>-- Ambil data failed NON DC dan SMS Project<br>SELECT DISTINCT wa_data.param1<br>FROM wa_data<br>LEFT JOIN wa_bulk_dr<br>ON wa_data.wa_id = wa_bulk_dr.messageid<br>WHERE DATE(wa_data.created_timestamp) = CURDATE() <br>AND wa_data.template_name IN(\'script_wa_project\')<br>AND (<br>(wa_data.source_sms = \'SMS PROJECT\'<br>AND TIME(wa_data.created_timestamp) >= \'18:00:00\'<br>)<br>OR<br>(wa_data.source_sms = \'SMS NON DC\'<br>AND TIME(wa_data.created_timestamp) >= \'08:00:00\'<br>))<br>AND (<br>wa_bulk_dr.status = \'failed\' OR wa_data.delivery_status = \'failed\'<br>);</p><p>2. lalu get data non dc dan sms project dilink berikut<br>   <a href=\"http://172.16.30.33:3108/c_smsproject\" target=\"_blank\">http://172.16.30.33:3108/c_smsproject</a> <br>   <a href=\"http://172.16.30.33:3108/c_setup_data_sms\" target=\"_blank\">http://172.16.30.33:3108/c_setup_data_sms</a></p><p>3. delete not in nomor kontrak pada failed non dc dan project yang sudah ditarik jalankan query contoh berikut<br>DELETE FROM sms_data WHERE noKontrak NOT IN( <br>\'701000170126\',<br>\'705001871824\',<br>\'426000124626\',<br>\'610000464125\',<br>\'503000959426\',<br>\'406000190826\',<br>\'421000115026\',<br>\'403000224425\',<br>\'709002436224\',<br>\'404001568825\',<br>\'278001620624\',<br>\'434000239326\',<br>\'312903429826\',<br>\'439000242626\',<br>\'550001523425\',<br>\'503005540124\',<br>\'550002726924\',<br>\'506000427926\',<br>\'414000568225\',<br>\'550001777925\',<br>\'543000368026\',<br>\'276003077124\',<br>\'276003084724\',<br>\'276000329226\',<br>\'602000421925\',<br>\'805003847126\',<br>\'508000237225\',<br>\'805002722525\',<br>\'414001667525\',<br>\'550000383926\',<br>\'506000259225\',<br>\'543000730326\',<br>\'531900298926\',<br>\'709000155226\',